begin;
select plan(12);
select has_table('public','best_book_selections','manual winners persisted');
select has_table('public','reading_activity_dates','explicit reading dates');
select is((select relrowsecurity from pg_class where oid='public.best_book_selections'::regclass),true,'selections RLS');
select is((select relrowsecurity from pg_class where oid='public.reading_activity_dates'::regclass),true,'activity RLS');
select ok(not has_table_privilege('authenticated','public.best_book_selections','INSERT'),'no raw selection insertion');
select ok(not has_table_privilege('authenticated','public.best_book_selections','UPDATE'),'no raw winner replacement');
select ok(not has_table_privilege('authenticated','public.reading_activity_dates','INSERT'),'no raw activity fabrication');
select ok(not has_table_privilege('anon','public.best_book_selections','SELECT'),'anonymous cannot read selections');
select ok(not has_table_privilege('anon','public.reading_activity_dates','SELECT'),'anonymous cannot read activity');
insert into auth.users(id) values('00000000-0000-0000-0000-000000000011');
insert into public.books(owner_id,id,title,author) values('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000012','Stats fixture','Author');
insert into public.readings(owner_id,id,book_id,status,progress_mode) values('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000012','read','page');
insert into public.best_book_selections(owner_id,id,scope,period,reading_id) values('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000014','month','2026-09','00000000-0000-0000-0000-000000000013');
insert into public.reading_activity_dates(owner_id,reading_id,activity_date,source,source_reference) values('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000013','2026-09-01','user','Explicit user date');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
select is((select count(*)::int from public.best_book_selections),1,'owner reads choice');
select is((select count(*)::int from public.reading_activity_dates),1,'owner reads activity');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000015',true);
select is((select count(*)::int from public.best_book_selections)+(select count(*)::int from public.reading_activity_dates),0,'other owner reads neither');
reset role;
select * from finish();rollback;
